export type PersonId = (typeof people)[number]["id"];
export type PhotoId = (typeof photos)[number]["id"];

/** Looks up a person by id. */
export function person(id: PersonId): MediaPerson {
  return people.find(entry => entry.id === id)!;
}

/** Looks up a photo by id. */
export function photo(id: PhotoId): MediaPhoto {
  return photos.find(entry => entry.id === id)!;
}

/** Square 400 px avatar path for a person id, for `src` props. */
export const avatar = (id: PersonId) => person(id).src;

/** 800 × 1000 portrait crop of the same photo, for image-led layouts. */
export const portrait = (id: PersonId) => `/media/people/portrait/${id}.jpg`;

/** The first `count` people, for avatar stacks and lists. */
export const peopleSample = (count: number) => people.slice(0, count);

.cta { container: cta / inline-size; background: var(--background); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); }
.cta *, .cta *::before, .cta *::after { box-sizing: border-box; }

.title { margin: 0; font-family: var(--font-display); font-size: clamp(var(--text-2xl), var(--text-base) + 3.4cqi, var(--text-4xl)); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); text-wrap: balance; }
.description { margin: 0; color: var(--text-secondary); font-size: var(--text-lg); line-height: var(--leading-body); text-wrap: pretty; }
.actions { display: flex; flex-wrap: wrap; gap: var(--space-group); }

/* Actions: the arrow leans forward on hover; links match the button shapes. */
.arrow { transition: transform var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .action:hover .arrow, .linkAction:hover .arrow { transform: translateX(3px); } }
.linkAction { display: inline-flex; height: var(--control-height-lg); align-items: center; justify-content: center; gap: var(--space-related); border: 1px solid transparent; border-radius: var(--radius-control); corner-shape: var(--corner-shape); padding: 0 var(--space-comfort); font-size: var(--text-sm); font-weight: 500; text-decoration: none; transition: background-color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard), transform var(--duration-instant) var(--ease-standard); }
.linkAction[data-size="sm"] { height: var(--control-height-sm); padding: 0 var(--space-inset); }
.linkAction[data-variant="primary"] { background: var(--foreground); color: var(--background); }
.linkAction[data-variant="secondary"] { border-color: var(--border); background: var(--surface); color: var(--foreground); }
.linkAction:active { transform: scale(.97); }

/* Centered: a closing section on one quiet surface. */
.centeredWrap { max-width: 1120px; margin: 0 auto; padding: var(--space-stage) var(--space-block); }
.centered { display: grid; justify-items: center; gap: var(--space-inset); border: 1px solid var(--border); border-radius: var(--radius-overlay); corner-shape: var(--corner-shape); padding: var(--space-screen) var(--space-block); background: color-mix(in oklab, var(--surface-muted) 45%, var(--surface)); text-align: center; }
.centered .title { max-width: 18ch; }
.centered .description { max-width: 34rem; }
.centered .actions { justify-content: center; margin-top: var(--space-inset); }
.note { display: inline-flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: var(--space-group); margin: var(--space-group) 0 0; color: var(--text-muted); font-size: var(--text-sm); }
.faces { display: flex; padding-left: var(--space-related); }
.faces img { display: block; width: 26px; height: 26px; margin-left: calc(var(--space-related) * -1); border: 2px solid var(--surface); border-radius: 50%; corner-shape: round; object-fit: cover; }

/* Split: copy beside a setup card that completes itself. */
.split { display: grid; max-width: 1120px; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: center; gap: var(--space-stage); margin: 0 auto; padding: var(--space-screen) var(--space-block); }
.splitCopy { display: grid; justify-items: start; gap: var(--space-inset); }
.splitCopy .actions { margin-top: var(--space-inset); }
.points { display: grid; gap: var(--space-related); margin: var(--space-related) 0 0; padding: 0; list-style: none; }
.points li { display: flex; align-items: center; gap: var(--space-group); color: var(--text-secondary); font-size: var(--text-sm); }
.points svg { flex: none; color: var(--success); }
